using System;using System.Linq;using System.Windows.Forms;namespace StudentAttendanceSystemVS2012{static class AccessAdminSmoke{[STAThread]static int Main(){try{Application.EnableVisualStyles();var db=new Database();using(var f=new MainForm(db,1,null,"admin","System Administrator","Admin")){f.Show();Application.DoEvents();foreach(Control x in f.Controls){ClickAll(x);}f.Close();}Console.WriteLine("ADMIN_SMOKE_OK");return 0;}catch(Exception e){Console.WriteLine(e);return 1;}}static void ClickAll(Control c){foreach(Control x in c.Controls){var b=x as Button;if(b!=null&&b.Dock==DockStyle.Top){Console.WriteLine("CLICK "+b.Text);b.PerformClick();Application.DoEvents();}ClickAll(x);}}}}

